import React from 'react';
import { graphql, PageProps, HeadFC } from 'gatsby';
import Layout from '../components/Layout';
import FeaturedPosts from '../components/FeaturedPosts';
import EmptyFeaturedState from '../components/EmptyFeaturedState';
import ArticleCard from '../components/ArticleCard';
import Sidebar from '../components/Sidebar';
import SEO from '../components/SEO';
import { slugifySeriesName } from '../utils/articlePath';
import '../styles/empty-featured.css';

interface ArticleFrontmatter {
  slug: string;
  title: string;
  excerpt: string;
  featuredImage: string;
  tags: string[];
  type: string;
  author: string;
  publishedAt: string;
  updatedAt: string;
  rating?: number;
  draft?: boolean;
  review?: {
    rating?: number;
  };
  series?: {
    name: string;
    order?: number;
    description?: string;
    featuredImage?: string;
  };
}

interface Article {
  id: string;
  html: string;
  fields: {
    readingTime: number;
  };
  frontmatter: ArticleFrontmatter;
}

interface IndexPageData {
  allMarkdownRemark: {
    nodes: Article[];
  };
}

const IndexPage: React.FC<PageProps<IndexPageData>> = ({ data }) => {
  
  // All published posts and reviews
  const articles = data.allMarkdownRemark.nodes;

  // Group articles by series
  const seriesMap = new Map<string, Article[]>();
  const standaloneArticles: Article[] = [];

  articles.forEach(article => {
    if (article.frontmatter.series?.name) {
      const seriesName = article.frontmatter.series.name;
      if (!seriesMap.has(seriesName)) {
        seriesMap.set(seriesName, []);
      }
      seriesMap.get(seriesName)!.push(article);
    } else {
      standaloneArticles.push(article);
    }
  });

  // Extract first article from each series (sorted by order, then publishedAt)
  const seriesFirstArticles: Article[] = [];
  seriesMap.forEach((seriesArticles) => {
    const sortedArticles = [...seriesArticles].sort((a, b) => {
      const orderA = a.frontmatter.series?.order ?? 999;
      const orderB = b.frontmatter.series?.order ?? 999;
      
      if (orderA !== orderB) {
        return orderA - orderB;
      }
      
      return new Date(a.frontmatter.publishedAt).getTime() - 
             new Date(b.frontmatter.publishedAt).getTime();
    });
    
    seriesFirstArticles.push(sortedArticles[0]);
  });

  // Combine standalone articles and series first articles
  const allDisplayArticles = [...standaloneArticles, ...seriesFirstArticles].sort((a, b) => {
    return new Date(b.frontmatter.publishedAt).getTime() - 
           new Date(a.frontmatter.publishedAt).getTime();
  });

  // Helper to map article for display (handles series vs standalone)
  const mapArticleForSlider = (article: Article, allArticles: Article[]) => {
    const isSeries = !!article.frontmatter.series?.name;
    
    if (isSeries) {
      const seriesName = article.frontmatter.series!.name;
      const seriesArticles = allArticles.filter(a => a.frontmatter.series?.name === seriesName);
      const sortedSeriesArticles = [...seriesArticles].sort((a, b) => {
        const orderA = a.frontmatter.series?.order ?? Infinity;
        const orderB = b.frontmatter.series?.order ?? Infinity;
        return orderA - orderB;
      });
      const firstArticle = sortedSeriesArticles[0];

      return {
        ...firstArticle,
        frontmatter: {
          ...firstArticle.frontmatter,
          slug: slugifySeriesName(seriesName),
          title: seriesName,
          excerpt: firstArticle.frontmatter.series?.description || `A comprehensive series covering ${seriesName.toLowerCase()}.`,
          featuredImage: firstArticle.frontmatter.series?.featuredImage || firstArticle.frontmatter.featuredImage || `/images/content/brewing/intro-to-making-mead/series-cover.png`,
        },
      };
    }
    
    return article;
  };

  // Get the first 7 posts for the featured section (5 slider + 2 highlighted)
  // Posts live here until pushed out by newer content
  const latestArticles = allDisplayArticles.slice(0, 7);

  // Ensure we have data to map
  const featuredArticles = latestArticles.length > 0 ? latestArticles.slice(0, Math.min(5, latestArticles.length)).map(article => {
    const mappedArticle = mapArticleForSlider(article, articles);
    const isSeries = !!mappedArticle.frontmatter.series?.name;
    return {
      slug: mappedArticle.frontmatter.slug,
      title: mappedArticle.frontmatter.title,
      excerpt: mappedArticle.frontmatter.excerpt,
      featuredImage: mappedArticle.frontmatter.featuredImage,
      tags: mappedArticle.frontmatter.tags,
      type: mappedArticle.frontmatter.type,
      publishedAt: mappedArticle.frontmatter.publishedAt,
      readingTime: mappedArticle.fields?.readingTime || 0,
      isSeries,
      // Don't pass seriesName for series cards — the slug is already the
      // series slug, and getArticlePath produces /series/{slug} (landing page)
      seriesName: isSeries ? undefined : mappedArticle.frontmatter.series?.name,
      isDraft: !!mappedArticle.frontmatter.draft,
    };
  }) : [];
  
  const highlightedArticles = latestArticles.length > 5 ? latestArticles.slice(5, 7).map(article => {
    const mappedArticle = mapArticleForSlider(article, articles);
    const isSeries = !!mappedArticle.frontmatter.series?.name;
    return {
      slug: mappedArticle.frontmatter.slug,
      title: mappedArticle.frontmatter.title,
      excerpt: mappedArticle.frontmatter.excerpt,
      featuredImage: mappedArticle.frontmatter.featuredImage,
      tags: mappedArticle.frontmatter.tags,
      type: mappedArticle.frontmatter.type,
      publishedAt: mappedArticle.frontmatter.publishedAt,
      readingTime: mappedArticle.fields?.readingTime || 0,
      isSeries,
      seriesName: isSeries ? undefined : mappedArticle.frontmatter.series?.name,
      isDraft: !!mappedArticle.frontmatter.draft,
    };
  }) : [];
  
  // Exclude ALL posts shown in the featured section from the article grid below
  const featuredSlugs = latestArticles.map(article => article.frontmatter.slug);

  // Recent articles: non-featured posts only
  const recentArticles = allDisplayArticles
    .filter(
      (article) =>
        !featuredSlugs.includes(article.frontmatter.slug)
    )
    .slice(0, 12)
    .map((article) => mapArticleForSlider(article, articles));

  return (
    <Layout>
      <div className="hm-container">
        {featuredArticles.length === 0 ? (
          <EmptyFeaturedState message="No recent posts" />
        ) : (
          <FeaturedPosts 
            sliderArticles={featuredArticles}
            highlightedArticles={highlightedArticles}
          />
        )}

        <div className="hm-content-sidebar-wrap">
          <main className="hm-primary-content">
            <div className="hm-article-grid">
              {recentArticles.map((article) => {
                const isSeries = !!article.frontmatter.series?.name;
                return (
                <ArticleCard
                  key={article.id}
                  slug={article.frontmatter.slug}
                  title={article.frontmatter.title}
                  excerpt={article.frontmatter.excerpt}
                  featuredImage={article.frontmatter.featuredImage}
                  tags={article.frontmatter.tags || []}
                  publishedAt={article.frontmatter.publishedAt}
                  readingTime={article.fields?.readingTime || 0}
                  isSeries={isSeries}
                  seriesName={isSeries ? undefined : article.frontmatter.series?.name}
                  rating={article.frontmatter.rating ?? article.frontmatter.review?.rating}
                  isDraft={!!article.frontmatter.draft}
                />
                );
              })}
            </div>
          </main>
          <aside className="hm-sidebar-desktop">
            <Sidebar />
          </aside>
        </div>
      </div>
    </Layout>
  );
};

export default IndexPage;

export const Head: HeadFC = () => (
  <SEO 
    title={undefined} 
    siteMetadata={{
      title: 'Joseph Crawford',
      description: 'A blog relating to technical topics such as programming, web development, and software engineering.',
      siteUrl: 'https://josephcrawford.com'
    }}
  />
);

export const query = graphql`
  query (
    $draftFilter: [Boolean]
  ) {
    allMarkdownRemark(
      sort: { frontmatter: { publishedAt: DESC } }
      limit: 150
      filter: { frontmatter: { slug: { ne: null }, draft: { in: $draftFilter } }, fileAbsolutePath: { regex: "//content/(posts|reviews|brewing)/" } }
    ) {
      nodes {
        id
        html
        fields {
          readingTime
        }
        frontmatter {
          slug
          title
          excerpt
          featuredImage
          tags
          type
          author
          publishedAt
          updatedAt
          rating
          draft
          review {
            rating
          }
          series {
            name
            order
            description
            featuredImage
          }
        }
      }
    }
  }
`;
