import React from 'react';
import { Link } from 'gatsby';
import { getArticlePath } from '../utils/articlePath';
import OptimizedImage from './OptimizedImage';
import DraftBadge from './DraftBadge';

export interface FeaturedArticle {
  slug: string;
  title: string;
  excerpt: string;
  featuredImage: string;
  tags: string[];
  type?: string;
  publishedAt: string;
  readingTime?: number;
  isSeries?: boolean;
  seriesName?: string;
  isDraft?: boolean;
}

interface FeaturedSliderProps {
  articles: FeaturedArticle[];
}

const FeaturedSlider: React.FC<FeaturedSliderProps> = ({ articles }) => {
  const [currentSlide, setCurrentSlide] = React.useState(0);

  const goToSlide = (index: number) => {
    setCurrentSlide(index);
  };

  const goToPrevious = () => {
    setCurrentSlide((prev) =>
      prev === 0 ? articles.length - 1 : prev - 1
    );
  };

  const goToNext = () => {
    setCurrentSlide((prev) => (prev + 1) % articles.length);
  };

  if (articles.length === 0) {
    return null;
  }

  const currentArticle = articles[currentSlide];
  const isReview = currentArticle.tags?.some(t => t.toLowerCase() === 'reviews') ?? false;
  const isBrewing = currentArticle.type === 'brewing-recipe' || (currentArticle.tags?.some(t => t.toLowerCase() === 'brewing') ?? false);
  const articlePath = getArticlePath(currentArticle.slug, currentArticle.isSeries, isReview, isBrewing, currentArticle.seriesName);

  return (
    <div className="hm-swiper hm-slider">
      <div className="hm-swiper-wrapper">
        <div className="hm-swiper-slide">
          <div className="hm-slide-holder">
            <div className="hm-slide-image">
              <OptimizedImage
                src={currentArticle.featuredImage}
                alt={currentArticle.title}
                loading="eager"
                sizes="(max-width: 768px) 100vw, (max-width: 1200px) 65vw, 1200px"
                fetchpriority="high"
              />
            </div>
            <div className="hm-fp-overlay">
              <Link
                className="hm-fp-link-overlay"
                to={articlePath}
                aria-label={currentArticle.title}
              />
              {currentArticle.isDraft && <DraftBadge size="md" />}
            </div>

          </div>
        </div>
      </div>

      {articles.length > 1 && (
        <>
          <button
            onClick={goToPrevious}
            className="hm-slider-nav hm-slider-prev"
            aria-label="Previous slide"
          >
            ‹
          </button>

          <button
            onClick={goToNext}
            className="hm-slider-nav hm-slider-next"
            aria-label="Next slide"
          >
            ›
          </button>

          <div className="hm-slider-pagination">
            {articles.map((_, index) => (
              <button
                key={index}
                onClick={() => goToSlide(index)}
                className={`hm-slider-dot ${
                  index === currentSlide ? 'active' : ''
                }`}
                aria-label={`Go to slide ${index + 1}`}
              />
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default FeaturedSlider;
